//******************************

char	**ft_split(char const *s, char c);	//classic split

//******************************
//******************************

void	size_and_pos()	//consigue la posicion inicial y las dimensiones del mapa
{
	int	i;
	int	j;
	
	
	
	i = 0;
	while (map[i] != 0)
	{
		
		j = 0;
		while (map[i][j] != '\0')
		{
			if (map[i][j] == '@')
			{
				row_pos = i;
				col_pos = j;
			}
			if (i == 0)
			{
				row_len++;
			}
			j++;
		}
		row_max++;
		i++;
	}
}

