void	map_print()
{
	int	i = 0;
	int	j = 0;
	
	while (i < row_max)
	{
		j = 0;
		while (j < row_len)
		{
			printf("%c", map[i][j]);
			j++;
		}
		printf("\n");
		i++;
	}
}


//*******************************
//*******************************

void	map_count()
{
	int	i = 0;
	int	j = 0;
	
	while (i < row_max)
	{
		j = 0;
		while (j < row_len)
		{
			if (map[i][j] == 'O')
			{
				total += (i*100) + j;
			}
			j++;
		}
		i++;
	}
}

